import 'package:better_phenikaa_schedule/features/giao_dien/kda_firestarter/kda_burn_field.dart';
import 'package:cryptography/cryptography.dart';
import 'package:flutter_test/flutter_test.dart';

void main(){
  test('native burn fields match the approved JavaScript byte for byte',() async {
    // Values independently generated by the original buildBurnField(42,9/16).
    final field=buildKdaBurnField({'seed':42,'aspect':9/16});
    for(final reference in {
      'arrival':'6ca148523d30f653a946e4c80b0535091723aee9e7064274a1e62b323e37c11f',
      'timing':'f367cc5a7969165717c566b4e54a0244ae98b0e3e62bc18c8780dfcb65a2a08a',
    }.entries){
      final digest=await Sha256().hash(field[reference.key]!);
      expect(digest.bytes.map((x)=>x.toRadixString(16).padLeft(2,'0')).join(),reference.value);
    }
  });
}
